INSERT INTO lessons (course_id, sort_order, title_ko, lesson_type, content, estimated_seconds) VALUES
('a1000000-0000-0000-0000-000000000004', 1, '트리 개념', 'flashcard', '{"cards":[{"front":"루트(Root)란 무엇인가?","back":"트리의 최상위 노드로, 부모 노드가 없는 유일한 노드입니다. 모든 노드는 루트에서 시작하는 경로로 접근할 수 있습니다.","hint":null},{"front":"리프(Leaf) 노드란 무엇인가?","back":"자식 노드가 없는 노드로, 트리의 말단 노드입니다. 단말 노드(Terminal Node)라고도 부릅니다.","hint":null},{"front":"부모(Parent)와 자식(Child) 노드의 관계는?","back":"간선(Edge)으로 직접 연결된 두 노드 중 위쪽 노드가 부모, 아래쪽 노드가 자식입니다. 하나의 부모는 여러 자식을 가질 수 있습니다.","hint":null},{"front":"형제(Sibling) 노드란 무엇인가?","back":"같은 부모 노드를 공유하는 노드들을 형제 노드라고 합니다. 같은 레벨에 위치합니다.","hint":null},{"front":"트리의 높이(Height)와 깊이(Depth)의 차이는?","back":"깊이는 루트에서 특정 노드까지의 간선 수입니다. 높이는 특정 노드에서 가장 깊은 리프까지의 간선 수입니다. 트리의 높이는 루트의 높이입니다.","hint":null}]}', 180),

('a1000000-0000-0000-0000-000000000004', 2, '이진 트리', 'flashcard', '{"cards":[{"front":"이진 트리(Binary Tree)의 정의는?","back":"각 노드가 최대 2개의 자식 노드(왼쪽, 오른쪽)를 가지는 트리 자료구조입니다.","hint":null},{"front":"완전 이진 트리(Complete Binary Tree)란?","back":"마지막 레벨을 제외한 모든 레벨이 완전히 채워져 있고, 마지막 레벨의 노드는 왼쪽부터 채워진 이진 트리입니다.","hint":null},{"front":"포화 이진 트리(Full/Perfect Binary Tree)란?","back":"모든 내부 노드가 정확히 2개의 자식을 가지며, 모든 리프 노드가 같은 레벨에 있는 이진 트리입니다. 노드 수는 2^(h+1)-1개입니다.","hint":null},{"front":"편향 이진 트리(Skewed Binary Tree)란?","back":"모든 노드가 왼쪽 또는 오른쪽 한 방향으로만 자식을 가지는 이진 트리입니다. 연결 리스트와 유사한 구조이며 탐색 효율이 O(n)으로 저하됩니다.","hint":null},{"front":"이진 트리를 Python 클래스로 어떻게 표현하나?","back":"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\n각 노드는 값과 왼쪽/오른쪽 자식 참조를 가집니다.","hint":null}]}', 180),

('a1000000-0000-0000-0000-000000000004', 3, '트리 순회 - 전위', 'reading', '{"questions":[{"question":"다음 코드의 출력은?","code":"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef preorder(node):\n    if node is None:\n        return\n    print(node.val, end='' '')\n    preorder(node.left)\n    preorder(node.right)\n\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\nroot.left.right = Node(5)\n\npreorder(root)","options":["1 2 4 5 3","4 2 5 1 3","4 5 2 3 1","1 3 2 5 4"],"correct_index":0,"explanation":"전위 순회는 루트→왼쪽→오른쪽 순서입니다. 루트(1) → 왼쪽 서브트리(2→4→5) → 오른쪽 서브트리(3) 순으로 방문하여 1 2 4 5 3이 출력됩니다."},{"question":"다음 코드의 출력은?","code":"def preorder_list(node, result=[]):\n    if node is None:\n        return result\n    result.append(node.val)\n    preorder_list(node.left, result)\n    preorder_list(node.right, result)\n    return result\n\nroot = Node(10)\nroot.left = Node(6)\nroot.right = Node(15)\nroot.left.left = Node(3)\nroot.right.right = Node(20)\n\nprint(preorder_list(root, []))","options":["[10, 6, 3, 15, 20]","[3, 6, 10, 15, 20]","[3, 6, 15, 20, 10]","[10, 15, 20, 6, 3]"],"correct_index":0,"explanation":"전위 순회(루트→좌→우)로 방문하면: 10 → 6 → 3 → (6의 오른쪽 없음) → 15 → (15의 왼쪽 없음) → 20 순서가 됩니다."},{"question":"다음 코드의 출력은?","code":"def preorder_iter(root):\n    if root is None:\n        return []\n    stack = [root]\n    result = []\n    while stack:\n        node = stack.pop()\n        result.append(node.val)\n        if node.right:\n            stack.append(node.right)\n        if node.left:\n            stack.append(node.left)\n    return result\n\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\nroot.left.right = Node(5)\n\nprint(preorder_iter(root))","options":["[1, 2, 4, 5, 3]","[1, 3, 2, 5, 4]","[4, 2, 5, 1, 3]","[1, 2, 3, 4, 5]"],"correct_index":0,"explanation":"스택을 이용한 반복적 전위 순회입니다. 오른쪽을 먼저 스택에 넣고 왼쪽을 나중에 넣으면, 왼쪽이 먼저 pop되어 전위 순회와 동일한 결과인 [1, 2, 4, 5, 3]이 출력됩니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 4, '트리 순회 - 중위/후위', 'quiz', '{"questions":[{"question":"다음 트리를 중위 순회(In-order)한 결과는?\n\n        1\n       / \\\n      2   3\n     / \\\n    4   5","code":null,"options":["4 2 5 1 3","1 2 4 5 3","4 5 2 3 1","1 2 3 4 5"],"correct_index":0,"explanation":"중위 순회는 왼쪽→루트→오른쪽 순서입니다. 4 → 2 → 5 → 1 → 3 순으로 방문합니다. BST에서 중위 순회를 하면 오름차순 정렬된 결과가 나옵니다."},{"question":"다음 트리를 후위 순회(Post-order)한 결과는?\n\n        1\n       / \\\n      2   3\n     / \\\n    4   5","code":null,"options":["4 5 2 3 1","1 2 4 5 3","4 2 5 1 3","3 5 4 2 1"],"correct_index":0,"explanation":"후위 순회는 왼쪽→오른쪽→루트 순서입니다. 4 → 5 → 2 → 3 → 1 순으로 방문합니다. 후위 순회는 자식을 먼저 처리한 뒤 부모를 처리하므로 트리 삭제에 유용합니다."},{"question":"중위 순회 결과가 [1, 2, 3, 4, 5]가 되는 트리 구조는 어떤 특성을 가지나요?","code":null,"options":["이진 탐색 트리(BST)의 특성을 만족한다","완전 이진 트리의 특성을 만족한다","포화 이진 트리의 특성을 만족한다","편향 트리의 특성을 만족한다"],"correct_index":0,"explanation":"BST에서 중위 순회를 수행하면 항상 오름차순으로 정렬된 결과가 나옵니다. 이는 BST의 핵심 특성인 왼쪽 < 루트 < 오른쪽 규칙 덕분입니다."},{"question":"전위, 중위, 후위 순회 중 트리 복사(Clone)에 가장 적합한 순회 방식은?","code":null,"options":["전위 순회","중위 순회","후위 순회","레벨 순회"],"correct_index":0,"explanation":"전위 순회(루트→좌→우)는 루트를 먼저 방문하므로 트리를 복사할 때 부모 노드를 먼저 생성하고 자식을 이후에 생성할 수 있어 트리 복사에 적합합니다."},{"question":"후위 순회가 특히 유용한 응용 분야는?","code":null,"options":["수식 트리에서 수식 계산","BST에서 정렬된 데이터 추출","트리 구조를 문자열로 직렬화","트리에서 최솟값 탐색"],"correct_index":0,"explanation":"후위 순회는 자식 노드를 먼저 처리한 뒤 부모 노드를 처리하므로, 수식 트리에서 피연산자(자식)를 먼저 계산한 뒤 연산자(부모)를 적용하는 수식 계산에 매우 유용합니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 5, 'BST 개념', 'flashcard', '{"cards":[{"front":"이진 탐색 트리(BST)의 핵심 규칙은?","back":"모든 노드에 대해: 왼쪽 서브트리의 모든 값 < 현재 노드 값 < 오른쪽 서브트리의 모든 값. 이 규칙이 재귀적으로 모든 서브트리에 적용됩니다.","hint":null},{"front":"BST에서 탐색의 시간 복잡도는?","back":"평균: O(log n) - 균형 잡힌 트리일 때\n최악: O(n) - 편향 트리일 때\n탐색마다 절반의 노드를 제거하므로 평균적으로 매우 효율적입니다.","hint":null},{"front":"BST의 중위 순회 결과는 어떤 특성을 가지나?","back":"BST를 중위 순회(왼쪽→루트→오른쪽)하면 항상 오름차순으로 정렬된 결과가 나옵니다. 이는 BST의 정렬 특성을 직접 반영합니다.","hint":null},{"front":"BST가 되기 위한 올바른 예시는?","back":"      8\n     / \\\n    3   10\n   / \\    \\\n  1   6    14\n     / \\\n    4   7\n\n각 노드의 왼쪽은 더 작고 오른쪽은 더 큰 값으로 구성됩니다.","hint":null},{"front":"BST와 일반 이진 트리의 차이점은?","back":"일반 이진 트리는 자식이 최대 2개라는 구조적 제약만 있습니다. BST는 추가적으로 값의 순서 규칙(왼쪽 < 루트 < 오른쪽)을 만족해야 하는 특수한 이진 트리입니다.","hint":null}]}', 180),

('a1000000-0000-0000-0000-000000000004', 6, 'BST 검색', 'fill_blank', '{"questions":[{"question":"BST에서 값을 재귀적으로 탐색하는 함수입니다. 빈칸에 알맞은 코드를 고르세요.","code":"def search(root, target):\n    if root is None:\n        return False\n    if root.val == target:\n        return True\n    if target < root.val:\n        return ___(root.left, target)\n    return search(root.right, target)","options":["search","insert","delete","traverse"],"correct_index":0,"explanation":"target이 현재 노드보다 작으면 왼쪽 서브트리에서 재귀적으로 탐색합니다. BST의 핵심 규칙인 왼쪽 < 루트 < 오른쪽을 활용합니다."},{"question":"BST 탐색에서 반복(iterative) 방식의 빈칸을 채우세요.","code":"def search_iter(root, target):\n    current = root\n    while current is not None:\n        if current.val == target:\n            return True\n        elif target < current.val:\n            current = current.left\n        else:\n            current = ___\n    return False","options":["current.right","current.left","current.parent","current.next"],"correct_index":0,"explanation":"target이 현재 노드보다 크면 오른쪽 자식으로 이동합니다. BST에서 큰 값은 오른쪽에 있으므로 current.right로 이동해야 합니다."},{"question":"BST에서 최솟값을 찾는 함수의 빈칸을 채우세요.","code":"def find_min(root):\n    current = root\n    while current.___ is not None:\n        current = current.left\n    return current.val","options":["left","right","parent","next"],"correct_index":0,"explanation":"BST에서 가장 작은 값은 가장 왼쪽에 있습니다. 왼쪽 자식이 없을 때까지 계속 왼쪽으로 이동하면 최솟값을 찾을 수 있습니다."},{"question":"BST에서 특정 노드를 반환하는 함수의 빈칸을 채우세요.","code":"def find_node(root, target):\n    if root is None or root.val == target:\n        return ___\n    if target < root.val:\n        return find_node(root.left, target)\n    return find_node(root.right, target)","options":["root","None","target","True"],"correct_index":0,"explanation":"노드를 찾았을 때(root.val == target) 또는 탐색 실패(root is None)일 때 root를 반환합니다. 찾은 경우 해당 노드 객체를, 못 찾은 경우 None을 반환합니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 7, 'BST 삽입', 'quiz', '{"questions":[{"question":"다음 BST에 값 7을 삽입하면 어느 위치에 삽입되나요?\n\n      8\n     / \\\n    3   10\n   / \\\n  1   6","code":null,"options":["6의 오른쪽 자식","3의 왼쪽 자식","8의 왼쪽 자식","10의 왼쪽 자식"],"correct_index":0,"explanation":"7을 삽입할 때: 8>7이므로 왼쪽(3) → 3<7이므로 오른쪽(6) → 6<7이므로 오른쪽으로 이동 → 6의 오른쪽이 비어 있으므로 그 자리에 삽입됩니다."},{"question":"다음 BST 삽입 코드에서 올바른 설명은?","code":"def insert(root, val):\n    if root is None:\n        return Node(val)\n    if val < root.val:\n        root.left = insert(root.left, val)\n    elif val > root.val:\n        root.right = insert(root.right, val)\n    return root","options":["중복값은 삽입하지 않는다","중복값은 왼쪽에 삽입된다","중복값은 오른쪽에 삽입된다","중복값 처리 로직이 없어 오류가 발생한다"],"correct_index":0,"explanation":"코드에서 val < root.val이면 왼쪽, val > root.val이면 오른쪽으로 이동합니다. 같은 경우(val == root.val)에는 어떤 분기도 실행되지 않고 현재 루트를 그대로 반환하므로 중복값은 삽입되지 않습니다."},{"question":"빈 BST에 순서대로 [5, 3, 7, 1, 4]를 삽입했을 때 루트의 왼쪽 자식의 오른쪽 자식 값은?","code":null,"options":["4","3","1","7"],"correct_index":0,"explanation":"삽입 순서: 5(루트) → 3(5의 왼쪽) → 7(5의 오른쪽) → 1(3의 왼쪽) → 4는 5보다 작으므로 왼쪽(3), 3보다 크므로 오른쪽에 위치. 따라서 루트(5)의 왼쪽 자식(3)의 오른쪽 자식은 4입니다."},{"question":"BST 삽입의 평균 시간 복잡도는?","code":null,"options":["O(log n)","O(n)","O(n log n)","O(1)"],"correct_index":0,"explanation":"균형 잡힌 BST에서 삽입 시 매 단계마다 탐색 범위가 절반으로 줄어들어 평균 O(log n)입니다. 단, 편향 트리의 경우 최악 O(n)이 됩니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 8, 'BST 삭제', 'quiz', '{"questions":[{"question":"BST에서 리프 노드(자식이 없는 노드)를 삭제하는 방법은?","code":null,"options":["해당 노드를 그냥 제거한다","자식 노드로 대체한다","중위 후계자로 대체한다","부모 노드를 삭제한다"],"correct_index":0,"explanation":"리프 노드는 자식이 없으므로 그냥 제거하면 됩니다. 부모 노드의 해당 방향 포인터를 None으로 설정하면 됩니다. 가장 단순한 경우입니다."},{"question":"BST에서 자식이 하나인 노드를 삭제하는 올바른 방법은?","code":null,"options":["삭제할 노드의 자식을 삭제할 노드의 위치로 올린다","삭제할 노드를 None으로 바꾼다","중위 후계자로 대체한다","자식 노드도 함께 삭제한다"],"correct_index":0,"explanation":"자식이 하나인 경우, 삭제할 노드를 제거하고 그 유일한 자식 노드를 삭제된 노드의 위치로 올립니다. 부모 노드가 삭제된 노드 대신 자식 노드를 가리키게 합니다."},{"question":"BST에서 자식이 둘인 노드를 삭제할 때 가장 일반적인 방법은?","code":null,"options":["중위 후계자(오른쪽 서브트리의 최솟값)의 값으로 대체 후 중위 후계자 삭제","왼쪽 자식으로 대체한다","오른쪽 자식으로 대체한다","노드의 값을 0으로 설정한다"],"correct_index":0,"explanation":"자식이 둘인 경우, 오른쪽 서브트리에서 가장 작은 값(중위 후계자)을 찾아 현재 노드의 값으로 복사한 후, 중위 후계자 노드를 삭제합니다. BST 규칙을 유지하는 방법입니다."},{"question":"다음 BST 삭제 코드에서 find_min 함수가 사용되는 이유는?","code":"def delete(root, val):\n    if root is None:\n        return root\n    if val < root.val:\n        root.left = delete(root.left, val)\n    elif val > root.val:\n        root.right = delete(root.right, val)\n    else:\n        if root.left is None:\n            return root.right\n        elif root.right is None:\n            return root.left\n        min_val = find_min(root.right)\n        root.val = min_val\n        root.right = delete(root.right, min_val)\n    return root","options":["자식이 둘인 경우 중위 후계자를 찾기 위해","리프 노드를 탐색하기 위해","삭제할 노드를 찾기 위해","트리의 최솟값을 출력하기 위해"],"correct_index":0,"explanation":"자식이 둘인 노드를 삭제할 때 오른쪽 서브트리의 최솟값(중위 후계자)을 find_min으로 찾습니다. 이 값으로 현재 노드를 대체하면 BST의 정렬 특성이 유지됩니다."},{"question":"다음 BST에서 노드 3을 삭제한 결과로 올바른 것은?\n\n      5\n     / \\\n    3   7\n   / \\\n  2   4","code":null,"options":["5의 왼쪽 자식이 4가 되고, 4의 왼쪽 자식이 2가 된다","5의 왼쪽 자식이 2가 된다","5의 왼쪽 자식이 삭제된다","트리 구조가 변하지 않는다"],"correct_index":0,"explanation":"3은 자식이 둘(2, 4)이므로 오른쪽 서브트리의 최솟값인 4로 대체하고, 4는 리프이므로 삭제합니다. 결과적으로 5의 왼쪽 자식은 4(값만 교체), 4의 왼쪽은 2, 오른쪽은 없습니다."}]}', 360),

('a1000000-0000-0000-0000-000000000004', 9, 'BST 유효성 검증', 'reading', '{"questions":[{"question":"다음 코드의 출력은?","code":"def is_valid_bst(node, min_val=float(''-inf''), max_val=float(''inf'')):\n    if node is None:\n        return True\n    if not (min_val < node.val < max_val):\n        return False\n    return (is_valid_bst(node.left, min_val, node.val) and\n            is_valid_bst(node.right, node.val, max_val))\n\nroot = Node(5)\nroot.left = Node(3)\nroot.right = Node(7)\nroot.left.left = Node(1)\nroot.left.right = Node(4)\n\nprint(is_valid_bst(root))","options":["True","False","None","오류 발생"],"correct_index":0,"explanation":"각 노드는 허용 범위 내의 값을 가져야 합니다. 루트(5)는 (-inf, inf), 왼쪽(3)은 (-inf, 5), 오른쪽(7)은 (5, inf) 범위를 체크합니다. 모든 노드가 조건을 만족하므로 True입니다."},{"question":"다음 코드의 출력은?","code":"def is_valid_bst(node, min_val=float(''-inf''), max_val=float(''inf'')):\n    if node is None:\n        return True\n    if not (min_val < node.val < max_val):\n        return False\n    return (is_valid_bst(node.left, min_val, node.val) and\n            is_valid_bst(node.right, node.val, max_val))\n\nroot = Node(5)\nroot.left = Node(3)\nroot.right = Node(7)\nroot.left.right = Node(6)  # 잘못된 위치\n\nprint(is_valid_bst(root))","options":["False","True","None","오류 발생"],"correct_index":0,"explanation":"노드 6은 3의 오른쪽 자식이지만, 루트(5)의 왼쪽 서브트리에 있으므로 5보다 작아야 합니다. is_valid_bst(node=6, min=3, max=5)를 체크할 때 6 < 5를 만족하지 않으므로 False를 반환합니다."},{"question":"다음 코드의 출력은?","code":"def is_valid_bst(node, min_val=float(''-inf''), max_val=float(''inf'')):\n    if node is None:\n        return True\n    if not (min_val < node.val < max_val):\n        return False\n    return (is_valid_bst(node.left, min_val, node.val) and\n            is_valid_bst(node.right, node.val, max_val))\n\n# 단순히 자식만 비교하는 잘못된 검증\ndef wrong_check(node):\n    if node is None:\n        return True\n    if node.left and node.left.val >= node.val:\n        return False\n    if node.right and node.right.val <= node.val:\n        return False\n    return wrong_check(node.left) and wrong_check(node.right)\n\nroot = Node(10)\nroot.left = Node(5)\nroot.right = Node(15)\nroot.left.right = Node(12)  # BST 위반\n\nprint(wrong_check(root), is_valid_bst(root))","options":["True False","False False","True True","False True"],"correct_index":0,"explanation":"wrong_check는 부모-자식 간의 관계만 확인하여 12가 5의 오른쪽(5<12)이므로 통과시킵니다. 하지만 is_valid_bst는 12가 루트(10)의 왼쪽 서브트리에 있으므로 반드시 10보다 작아야 한다는 전역 범위 조건을 체크하여 False를 반환합니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 10, '레벨 순회 BFS', 'fill_blank', '{"questions":[{"question":"큐를 이용한 레벨 순회(BFS)입니다. 빈칸에 알맞은 코드를 고르세요.","code":"from collections import deque\n\ndef level_order(root):\n    if root is None:\n        return []\n    queue = ___()\n    queue.append(root)\n    result = []\n    while queue:\n        node = queue.popleft()\n        result.append(node.val)\n        if node.left:\n            queue.append(node.left)\n        if node.right:\n            queue.append(node.right)\n    return result","options":["deque","list","stack","set"],"correct_index":0,"explanation":"레벨 순회(BFS)는 큐(Queue)를 사용합니다. Python에서는 collections.deque가 popleft() 연산을 O(1)에 수행하므로 BFS 구현에 적합합니다. list의 pop(0)는 O(n)으로 비효율적입니다."},{"question":"레벨별로 그룹화하는 BFS의 빈칸을 채우세요.","code":"from collections import deque\n\ndef level_order_groups(root):\n    if not root:\n        return []\n    queue = deque([root])\n    result = []\n    while queue:\n        level_size = ___(queue)\n        level = []\n        for _ in range(level_size):\n            node = queue.popleft()\n            level.append(node.val)\n            if node.left: queue.append(node.left)\n            if node.right: queue.append(node.right)\n        result.append(level)\n    return result","options":["len","sum","max","min"],"correct_index":0,"explanation":"현재 레벨의 노드 수를 파악하기 위해 while 루프 시작 시 len(queue)로 현재 큐의 크기를 저장합니다. 이 크기만큼만 처리하면 한 레벨의 모든 노드를 그룹으로 묶을 수 있습니다."},{"question":"BFS로 트리의 가장 오른쪽 노드를 찾는 코드의 빈칸을 채우세요.","code":"from collections import deque\n\ndef right_side_view(root):\n    if not root:\n        return []\n    queue = deque([root])\n    result = []\n    while queue:\n        level_size = len(queue)\n        for i in range(level_size):\n            node = queue.popleft()\n            if i == ___:\n                result.append(node.val)\n            if node.left: queue.append(node.left)\n            if node.right: queue.append(node.right)\n    return result","options":["level_size - 1","0","level_size","level_size + 1"],"correct_index":0,"explanation":"각 레벨에서 마지막 노드(가장 오른쪽)는 인덱스 level_size - 1입니다. i == level_size - 1일 때 해당 노드의 값을 결과에 추가하면 각 레벨의 오른쪽 끝 노드를 수집할 수 있습니다."},{"question":"BFS의 공간 복잡도에 대한 설명으로 빈칸에 알맞은 것은?","code":"# 완전 이진 트리에서 BFS 실행 시\n# 최대 큐 크기는 마지막 레벨의 노드 수\n# n개의 노드를 가진 완전 이진 트리의\n# 마지막 레벨 노드 수는 최대 n/2개\n\n# 따라서 BFS의 공간 복잡도는\nspace_complexity = ''O(___)''","options":["n","log n","n log n","1"],"correct_index":0,"explanation":"BFS의 공간 복잡도는 O(n)입니다. 완전 이진 트리에서 마지막 레벨에 최대 n/2개의 노드가 있어 큐에 최대 O(n)개의 노드가 저장될 수 있습니다. DFS(재귀)의 공간 복잡도는 O(h)=O(log n)으로 더 효율적입니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 11, '트리 높이 구하기', 'quiz', '{"questions":[{"question":"다음 트리의 높이(height)는 얼마인가요?\n\n      1\n     / \\\n    2   3\n   / \\\n  4   5\n /\n6","code":null,"options":["3","2","4","1"],"correct_index":0,"explanation":"트리의 높이는 루트에서 가장 깊은 리프까지의 간선 수입니다. 루트(1) → 2 → 4 → 6 경로가 가장 길며 간선 수가 3이므로 높이는 3입니다."},{"question":"다음 재귀적 트리 높이 계산 코드에서 올바른 빈칸은?","code":"def height(node):\n    if node is None:\n        return -1\n    left_h = height(node.left)\n    right_h = height(node.right)\n    return max(left_h, right_h) + ___","options":["1","0","-1","2"],"correct_index":0,"explanation":"현재 노드의 높이는 왼쪽과 오른쪽 서브트리 중 더 높은 쪽에 1을 더한 값입니다. max(left_h, right_h) + 1로 계산합니다. 리프 노드의 경우 max(-1, -1) + 1 = 0이 됩니다."},{"question":"노드 개수가 n인 완전 이진 트리의 높이는?","code":null,"options":["⌊log₂n⌋","n-1","n/2","⌈log₂n⌉"],"correct_index":0,"explanation":"완전 이진 트리에서 h 높이의 트리는 최대 2^(h+1)-1개의 노드를 가집니다. 따라서 n개의 노드를 가진 완전 이진 트리의 높이는 ⌊log₂n⌋입니다. 이것이 BST가 평균 O(log n) 탐색 복잡도를 가지는 이유입니다."},{"question":"다음 코드를 실행했을 때 출력되는 값은?","code":"def height(node):\n    if node is None:\n        return -1\n    return max(height(node.left), height(node.right)) + 1\n\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\n\nprint(height(root))","options":["2","1","3","0"],"correct_index":0,"explanation":"height(4)=-1+1=0, height(Node(2))=max(0,-1)+1=1, height(Node(3))=-1+1=0, height(root)=max(1,0)+1=2. 루트의 높이는 2입니다."},{"question":"균형 이진 트리(Balanced Binary Tree)의 조건으로 올바른 것은?","code":null,"options":["모든 노드에서 왼쪽과 오른쪽 서브트리의 높이 차이가 1 이하","모든 레벨이 완전히 채워져 있음","모든 리프 노드가 같은 레벨에 있음","루트에서 모든 리프까지 경로 길이가 동일함"],"correct_index":0,"explanation":"균형 이진 트리는 모든 노드에서 왼쪽과 오른쪽 서브트리의 높이 차이(Balance Factor)가 최대 1인 트리입니다. AVL 트리가 이 조건을 엄격히 유지하는 대표적인 자료구조입니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 12, '균형 트리', 'flashcard', '{"cards":[{"front":"AVL 트리란 무엇인가?","back":"모든 노드에서 왼쪽과 오른쪽 서브트리의 높이 차이(Balance Factor)가 -1, 0, 1 중 하나인 자기 균형 이진 탐색 트리입니다. 삽입/삭제 후 회전 연산으로 균형을 유지합니다.","hint":null},{"front":"AVL 트리의 회전 연산 4가지는?","back":"1. LL 회전 (우회전): 왼쪽-왼쪽 불균형\n2. RR 회전 (좌회전): 오른쪽-오른쪽 불균형\n3. LR 회전 (좌-우 이중회전): 왼쪽-오른쪽 불균형\n4. RL 회전 (우-좌 이중회전): 오른쪽-왼쪽 불균형","hint":null},{"front":"레드-블랙 트리(Red-Black Tree)란?","back":"각 노드에 색(빨강/검정)을 부여하는 자기 균형 BST입니다. 규칙: 루트는 검정, 빨간 노드의 자식은 검정, 루트~리프 경로의 검정 노드 수 동일. AVL보다 느슨한 균형으로 삽입/삭제가 빠릅니다.","hint":null},{"front":"AVL 트리 vs 레드-블랙 트리의 차이는?","back":"AVL 트리: 더 엄격한 균형, 탐색이 빠름(읽기 많은 경우 유리)\n레드-블랙 트리: 느슨한 균형, 삽입/삭제가 빠름(쓰기 많은 경우 유리)\nPython의 dict, Java의 TreeMap은 레드-블랙 트리 기반입니다.","hint":null},{"front":"균형 트리가 필요한 이유는?","back":"일반 BST는 편향(skewed)될 경우 탐색이 O(n)으로 저하됩니다. 균형 트리는 항상 O(log n) 높이를 유지하여 탐색, 삽입, 삭제 모두 O(log n)을 보장합니다.","hint":null}]}', 180),

('a1000000-0000-0000-0000-000000000004', 13, '그래프 개념', 'flashcard', '{"cards":[{"front":"그래프(Graph)의 기본 구성 요소는?","back":"정점(Vertex/Node): 데이터를 저장하는 단위\n간선(Edge): 정점 간의 연결 관계\n그래프 G = (V, E)로 표현하며 V는 정점 집합, E는 간선 집합입니다.","hint":null},{"front":"방향 그래프와 무방향 그래프의 차이는?","back":"방향 그래프(Directed Graph): 간선에 방향이 있어 A→B는 A에서 B로만 이동 가능\n무방향 그래프(Undirected Graph): 간선에 방향이 없어 A-B는 양방향 이동 가능\nSNS 팔로우는 방향, 친구 관계는 무방향 그래프입니다.","hint":null},{"front":"가중치 그래프(Weighted Graph)란?","back":"각 간선에 가중치(Weight)가 부여된 그래프입니다. 도로 네트워크에서 거리, 네트워크에서 대역폭 등을 표현할 때 사용합니다. 최단 경로 알고리즘(다익스트라, 벨만-포드)에서 활용됩니다.","hint":null},{"front":"차수(Degree)의 정의는?","back":"무방향 그래프: 한 정점에 연결된 간선의 수\n방향 그래프: 진입 차수(In-degree) = 들어오는 간선 수, 진출 차수(Out-degree) = 나가는 간선 수\n모든 정점의 차수 합 = 간선 수 × 2 (무방향)","hint":null},{"front":"트리와 그래프의 관계는?","back":"트리는 그래프의 특수한 형태입니다. 트리는 사이클이 없는 연결된 무방향 그래프(DAG의 특수형)입니다. n개의 정점을 가진 트리는 정확히 n-1개의 간선을 가집니다.","hint":null}]}', 180),

('a1000000-0000-0000-0000-000000000004', 14, '그래프 표현', 'quiz', '{"questions":[{"question":"인접 행렬(Adjacency Matrix)로 그래프를 표현할 때의 공간 복잡도는?","code":null,"options":["O(V²)","O(V+E)","O(E)","O(V)"],"correct_index":0,"explanation":"인접 행렬은 V×V 크기의 2차원 배열로 표현하므로 공간 복잡도는 O(V²)입니다. 간선 수에 관계없이 V² 공간을 사용하므로 간선이 적은 희소 그래프에는 비효율적입니다."},{"question":"인접 리스트(Adjacency List)로 그래프를 표현할 때의 특징으로 올바른 것은?","code":null,"options":["공간 복잡도가 O(V+E)로 희소 그래프에 효율적이다","두 정점의 연결 여부를 O(1)에 확인할 수 있다","항상 인접 행렬보다 빠르다","메모리를 V² 만큼 사용한다"],"correct_index":0,"explanation":"인접 리스트는 각 정점마다 연결된 정점 목록을 저장하므로 O(V+E) 공간을 사용합니다. 간선이 적은 희소 그래프에서 인접 행렬보다 공간 효율적입니다. 단, 두 정점의 연결 확인은 O(degree)가 필요합니다."},{"question":"다음 Python 코드로 표현된 그래프의 간선 수는?","code":"graph = {\n    0: [1, 2],\n    1: [0, 3],\n    2: [0, 3],\n    3: [1, 2]\n}\n# 무방향 그래프","options":["4","8","3","6"],"correct_index":0,"explanation":"인접 리스트에서 각 간선은 양방향으로 두 번 저장됩니다. 전체 리스트 항목 수는 8이므로 실제 간선 수는 8/2 = 4개입니다. 간선: (0,1), (0,2), (1,3), (2,3)"},{"question":"두 정점의 연결 여부를 가장 빠르게 확인할 수 있는 그래프 표현 방식은?","code":null,"options":["인접 행렬","인접 리스트","간선 리스트","해시맵"],"correct_index":0,"explanation":"인접 행렬에서는 matrix[u][v]를 O(1)에 확인할 수 있습니다. 인접 리스트는 해당 정점의 연결 목록을 순회해야 하므로 O(degree) 시간이 필요합니다."},{"question":"소셜 네트워크(수백만 사용자, 각 사용자가 평균 수백 명 연결)에 가장 적합한 그래프 표현은?","code":null,"options":["인접 리스트","인접 행렬","둘 다 동등하다","간선 행렬"],"correct_index":0,"explanation":"수백만 사용자의 경우 인접 행렬은 수조 개의 셀이 필요하지만, 실제 연결은 극히 일부입니다. 이런 희소 그래프에는 실제 연결만 저장하는 인접 리스트가 O(V+E) 공간으로 훨씬 효율적입니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 15, 'DFS 깊이우선', 'fill_blank', '{"questions":[{"question":"재귀를 이용한 DFS 구현에서 빈칸을 채우세요.","code":"def dfs_recursive(graph, node, visited=None):\n    if visited is None:\n        visited = set()\n    ___.add(node)\n    print(node, end='' '')\n    for neighbor in graph[node]:\n        if neighbor not in visited:\n            dfs_recursive(graph, neighbor, visited)\n    return visited","options":["visited","graph","node","neighbor"],"correct_index":0,"explanation":"방문한 노드를 추적하기 위해 visited 집합에 현재 노드를 추가합니다. visited.add(node)로 현재 노드를 방문 처리하여 중복 방문과 무한 루프를 방지합니다."},{"question":"스택을 이용한 반복적 DFS에서 빈칸을 채우세요.","code":"def dfs_iterative(graph, start):\n    visited = set()\n    stack = [start]\n    result = []\n    while stack:\n        node = stack.___()\n        if node not in visited:\n            visited.add(node)\n            result.append(node)\n            for neighbor in graph[node]:\n                if neighbor not in visited:\n                    stack.append(neighbor)\n    return result","options":["pop","popleft","dequeue","get"],"correct_index":0,"explanation":"DFS에서 스택의 마지막 원소를 꺼내야 하므로 pop()을 사용합니다. pop()은 리스트의 마지막(top) 원소를 제거하고 반환합니다. popleft()는 큐(BFS)에 사용됩니다."},{"question":"DFS로 연결 여부를 확인하는 코드의 빈칸을 채우세요.","code":"def is_connected(graph, start, end):\n    visited = set()\n    stack = [start]\n    while stack:\n        node = stack.pop()\n        if node == ___:\n            return True\n        if node not in visited:\n            visited.add(node)\n            for neighbor in graph[node]:\n                stack.append(neighbor)\n    return False","options":["end","start","None","visited"],"correct_index":0,"explanation":"현재 노드가 목적지(end)와 같으면 경로가 존재하므로 True를 반환합니다. 스택이 빌 때까지 end를 찾지 못하면 False를 반환합니다."},{"question":"DFS의 시간 복잡도는? (V: 정점 수, E: 간선 수)","code":"# 인접 리스트를 사용하는 경우\n# 각 정점은 한 번만 방문\n# 각 간선은 두 번 확인 (무방향 그래프)\n\ntime_complexity = ''O(___)''","options":["V + E","V * E","V²","E²"],"correct_index":0,"explanation":"DFS는 모든 정점을 한 번씩 방문하고(O(V)) 각 간선을 확인합니다(O(E)). 인접 리스트를 사용할 때 전체 시간 복잡도는 O(V+E)입니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 16, 'BFS 너비우선', 'fill_blank', '{"questions":[{"question":"BFS 구현에서 큐를 초기화하는 빈칸을 채우세요.","code":"from collections import deque\n\ndef bfs(graph, start):\n    visited = set([start])\n    queue = ___()\n    queue.append(start)\n    result = []\n    while queue:\n        node = queue.popleft()\n        result.append(node)\n        for neighbor in graph[node]:\n            if neighbor not in visited:\n                visited.add(neighbor)\n                queue.append(neighbor)\n    return result","options":["deque","list","set","dict"],"correct_index":0,"explanation":"BFS는 큐(Queue) 자료구조를 사용합니다. Python에서 collections.deque는 popleft()를 O(1)에 수행하여 BFS에 최적입니다. list를 사용하면 pop(0)이 O(n)으로 비효율적입니다."},{"question":"BFS로 최단 경로 거리를 구하는 코드의 빈칸을 채우세요.","code":"from collections import deque\n\ndef bfs_distance(graph, start, end):\n    queue = deque([(start, 0)])\n    visited = set([start])\n    while queue:\n        node, dist = queue.popleft()\n        if node == end:\n            return ___\n        for neighbor in graph[node]:\n            if neighbor not in visited:\n                visited.add(neighbor)\n                queue.append((neighbor, dist + 1))\n    return -1","options":["dist","dist + 1","0","node"],"correct_index":0,"explanation":"목적지에 도달했을 때 현재까지의 거리 dist를 반환합니다. BFS는 레벨 순서대로 탐색하므로 처음 목적지에 도달했을 때의 거리가 최단 거리임이 보장됩니다."},{"question":"BFS에서 노드를 큐에 넣을 때 방문 처리를 언제 해야 하나요? 빈칸을 채우세요.","code":"def bfs_correct(graph, start):\n    visited = set()\n    queue = deque([start])\n    ___.add(start)  # 큐에 넣을 때 방문 처리\n    while queue:\n        node = queue.popleft()\n        for neighbor in graph[node]:\n            if neighbor not in visited:\n                visited.add(neighbor)\n                queue.append(neighbor)\n    return visited","options":["visited","queue","graph","result"],"correct_index":0,"explanation":"BFS에서는 노드를 큐에 넣을 때 즉시 방문 처리해야 합니다. 큐에서 꺼낼 때 방문 처리하면 같은 노드가 여러 번 큐에 추가되어 중복 처리가 발생할 수 있습니다."},{"question":"BFS로 그래프의 모든 연결 요소를 찾는 코드의 빈칸을 채우세요.","code":"from collections import deque\n\ndef count_components(graph):\n    visited = set()\n    count = 0\n    for node in graph:\n        if node not in visited:\n            ___  += 1\n            queue = deque([node])\n            visited.add(node)\n            while queue:\n                curr = queue.popleft()\n                for neighbor in graph[curr]:\n                    if neighbor not in visited:\n                        visited.add(neighbor)\n                        queue.append(neighbor)\n    return count","options":["count","visited","queue","graph"],"correct_index":0,"explanation":"아직 방문하지 않은 노드에서 BFS를 시작할 때마다 새로운 연결 요소를 발견한 것이므로 count를 1 증가시킵니다. BFS가 끝나면 해당 연결 요소의 모든 노드가 visited에 추가됩니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 17, 'DFS vs BFS', 'quiz', '{"questions":[{"question":"미로에서 출구까지 가는 경로가 존재하는지 확인할 때 적합한 알고리즘은?","code":null,"options":["DFS (경로 존재 여부만 확인)","BFS (최단 경로 보장 필요)","둘 다 동일하다","인접 행렬이 필요하다"],"correct_index":0,"explanation":"경로의 존재 여부만 확인할 때는 DFS가 적합합니다. DFS는 한 방향으로 깊이 탐색하므로 메모리 효율적이며 재귀로 간단히 구현됩니다. 최단 경로가 필요하면 BFS를 사용해야 합니다."},{"question":"SNS에서 두 사람 사이의 최소 관계 단계(최단 경로)를 찾을 때 적합한 알고리즘은?","code":null,"options":["BFS","DFS","이진 탐색","해시 탐색"],"correct_index":0,"explanation":"BFS는 가중치가 없는 그래프에서 최단 경로를 보장합니다. 레벨 순서대로 탐색하므로 처음 목적지에 도달했을 때가 항상 최단 경로입니다. 6단계 분리 이론 확인에 활용됩니다."},{"question":"DFS가 BFS보다 유리한 경우는?","code":null,"options":["목적지가 트리의 깊은 곳에 있을 때","목적지가 시작점과 가까울 때","최단 경로를 찾아야 할 때","그래프가 매우 넓을 때"],"correct_index":0,"explanation":"DFS는 한 경로를 끝까지 탐색하므로 답이 깊은 곳에 있을 때 효율적입니다. 반면 BFS는 레벨 순서로 탐색하므로 넓은 그래프에서는 큐에 많은 노드를 저장해야 합니다."},{"question":"DFS와 BFS의 공간 복잡도를 비교할 때 올바른 설명은?","code":null,"options":["DFS: O(h), BFS: O(w) (h=높이, w=최대 너비)","DFS: O(n), BFS: O(log n)","DFS: O(1), BFS: O(n)","둘 다 항상 O(n)이다"],"correct_index":0,"explanation":"DFS는 재귀 스택에 경로 상의 노드만 저장하므로 O(h) 공간이 필요합니다. BFS는 한 레벨의 모든 노드를 큐에 저장하므로 O(w) 공간이 필요합니다. 넓고 얕은 트리에서는 DFS가, 깊고 좁은 트리에서는 BFS가 공간 효율적입니다."},{"question":"위상 정렬(Topological Sort) 구현에 일반적으로 사용되는 탐색 방법은?","code":null,"options":["DFS","BFS","둘 다 사용 가능","이진 탐색"],"correct_index":0,"explanation":"위상 정렬은 DFS를 사용하는 방법과 BFS(Kahn''s algorithm)를 사용하는 방법 모두 있습니다. DFS 기반은 후위 순서의 역순으로 결과를 얻으며, BFS 기반은 진입 차수 0인 노드부터 처리합니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 18, '연결 요소', 'reading', '{"questions":[{"question":"다음 코드의 출력은?","code":"def find_components(graph):\n    visited = set()\n    components = []\n\n    def dfs(node, component):\n        visited.add(node)\n        component.append(node)\n        for neighbor in graph[node]:\n            if neighbor not in visited:\n                dfs(neighbor, component)\n\n    for node in graph:\n        if node not in visited:\n            component = []\n            dfs(node, component)\n            components.append(sorted(component))\n\n    return len(components)\n\ngraph = {\n    0: [1, 2],\n    1: [0],\n    2: [0],\n    3: [4],\n    4: [3],\n    5: []\n}\nprint(find_components(graph))","options":["3","1","2","6"],"correct_index":0,"explanation":"{0,1,2}, {3,4}, {5} 세 개의 연결 요소가 있습니다. 0-1-2는 서로 연결, 3-4는 서로 연결, 5는 독립된 노드입니다. 따라서 3을 출력합니다."},{"question":"다음 코드의 출력은?","code":"from collections import deque\n\ndef is_bipartite(graph):\n    color = {}\n    for start in graph:\n        if start not in color:\n            queue = deque([start])\n            color[start] = 0\n            while queue:\n                node = queue.popleft()\n                for neighbor in graph[node]:\n                    if neighbor not in color:\n                        color[neighbor] = 1 - color[node]\n                        queue.append(neighbor)\n                    elif color[neighbor] == color[node]:\n                        return False\n    return True\n\ngraph = {\n    0: [1, 3],\n    1: [0, 2],\n    2: [1, 3],\n    3: [0, 2]\n}\nprint(is_bipartite(graph))","options":["True","False","None","오류 발생"],"correct_index":0,"explanation":"이 그래프는 사각형(0-1-2-3-0)으로 짝수 사이클입니다. 0과 2를 색 0, 1과 3을 색 1로 칠하면 인접한 노드가 항상 다른 색을 가집니다. 따라서 이분 그래프이므로 True입니다."},{"question":"다음 코드의 출력은?","code":"def has_cycle_undirected(graph):\n    visited = set()\n\n    def dfs(node, parent):\n        visited.add(node)\n        for neighbor in graph[node]:\n            if neighbor not in visited:\n                if dfs(neighbor, node):\n                    return True\n            elif neighbor != parent:\n                return True\n        return False\n\n    for node in graph:\n        if node not in visited:\n            if dfs(node, -1):\n                return True\n    return False\n\ngraph = {\n    0: [1, 2],\n    1: [0, 2],\n    2: [0, 1]\n}\nprint(has_cycle_undirected(graph))","options":["True","False","None","오류 발생"],"correct_index":0,"explanation":"그래프 0-1-2-0은 삼각형으로 사이클이 존재합니다. DFS로 0→1→2를 방문할 때, 2의 이웃인 0이 이미 방문되었고 1(부모)이 아니므로 사이클을 감지하여 True를 반환합니다."},{"question":"다음 코드의 출력은?","code":"def connected_components_sizes(graph):\n    visited = set()\n    sizes = []\n\n    def dfs(node):\n        visited.add(node)\n        size = 1\n        for neighbor in graph[node]:\n            if neighbor not in visited:\n                size += dfs(neighbor)\n        return size\n\n    for node in sorted(graph.keys()):\n        if node not in visited:\n            sizes.append(dfs(node))\n\n    return sizes\n\ngraph = {\n    0: [1], 1: [0],\n    2: [3, 4], 3: [2], 4: [2],\n    5: []\n}\nprint(connected_components_sizes(graph))","options":["[2, 3, 1]","[1, 2, 3]","[3, 2, 1]","[2, 1, 3]"],"correct_index":0,"explanation":"노드를 정렬된 순서로 순회합니다. 0에서 시작: {0,1} → 크기 2. 2에서 시작: {2,3,4} → 크기 3. 5에서 시작: {5} → 크기 1. 따라서 [2, 3, 1]이 출력됩니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 19, '위상 정렬', 'quiz', '{"questions":[{"question":"위상 정렬(Topological Sort)이 가능한 그래프의 조건은?","code":null,"options":["DAG (Directed Acyclic Graph: 방향 비순환 그래프)","무방향 그래프","사이클이 있는 방향 그래프","완전 그래프"],"correct_index":0,"explanation":"위상 정렬은 방향 비순환 그래프(DAG)에서만 가능합니다. 사이클이 있으면 선후 관계가 모순되어 위상 정렬이 불가능합니다. 강의 선수과목, 작업 스케줄링 등에 활용됩니다."},{"question":"진입 차수(In-degree) 기반 위상 정렬(Kahn''s algorithm)의 첫 번째 단계는?","code":null,"options":["진입 차수가 0인 모든 노드를 큐에 넣는다","DFS로 모든 노드를 방문한다","루트 노드부터 BFS를 시작한다","간선 수가 가장 많은 노드부터 처리한다"],"correct_index":0,"explanation":"Kahn''s algorithm에서는 먼저 모든 노드의 진입 차수를 계산하고, 진입 차수가 0인 노드(선수 조건이 없는 노드)를 모두 큐에 넣어 시작합니다."},{"question":"다음 의존 관계에서 올바른 위상 정렬 순서는?\n\n자료구조 → 알고리즘\n프로그래밍 기초 → 자료구조\n수학 → 알고리즘","code":null,"options":["프로그래밍 기초 → 수학 → 자료구조 → 알고리즘","알고리즘 → 자료구조 → 프로그래밍 기초 → 수학","자료구조 → 프로그래밍 기초 → 알고리즘 → 수학","수학 → 알고리즘 → 자료구조 → 프로그래밍 기초"],"correct_index":0,"explanation":"선수과목이 없는 것부터: 프로그래밍 기초와 수학을 먼저 수강. 그 다음 자료구조(프로그래밍 기초 완료), 마지막으로 알고리즘(자료구조 + 수학 완료). 따라서 프로그래밍 기초 → 수학 → 자료구조 → 알고리즘 순서가 가능합니다."},{"question":"위상 정렬 결과가 유일하지 않은 경우는?","code":null,"options":["동일 진입 차수 0인 노드가 여러 개인 경우","그래프에 사이클이 있는 경우","노드가 하나인 경우","선형 그래프인 경우"],"correct_index":0,"explanation":"위상 정렬 결과는 유일하지 않을 수 있습니다. 특정 단계에서 진입 차수가 0인 노드가 여러 개이면, 그들의 처리 순서에 따라 다른 위상 정렬 결과가 나올 수 있습니다."},{"question":"Kahn''s 알고리즘으로 위상 정렬 후 결과 리스트의 크기가 전체 노드 수보다 작으면 무엇을 의미하나?","code":null,"options":["그래프에 사이클이 존재한다","그래프가 연결되어 있지 않다","노드가 방문되지 않았다","간선이 충분하지 않다"],"correct_index":0,"explanation":"Kahn''s 알고리즘에서 결과 리스트 크기 < 전체 노드 수이면 일부 노드의 진입 차수가 0이 되지 않은 것으로, 사이클이 존재함을 의미합니다. 이를 통해 사이클 감지에도 활용됩니다."}]}', 300),

('a1000000-0000-0000-0000-000000000004', 20, '트리/그래프 종합', 'quiz', '{"questions":[{"question":"n개의 노드를 가진 완전 이진 트리에서 BFS 탐색의 시간 복잡도는?","code":null,"options":["O(n)","O(n log n)","O(log n)","O(n²)"],"correct_index":0,"explanation":"BFS는 모든 노드를 한 번씩 방문하므로 시간 복잡도는 O(n)입니다. 노드 수에 비례하여 탐색합니다."},{"question":"다음 중 BST, 힙(Heap), 일반 이진 트리의 특성을 올바르게 설명한 것은?","code":null,"options":["BST: 중위 순회 시 정렬됨, 힙: 부모가 항상 자식보다 크거나 작음, 일반 이진 트리: 순서 제약 없음","BST: 항상 균형, 힙: 탐색 O(log n), 일반 이진 트리: 삽입 O(1)","BST: 완전 이진 트리, 힙: 탐색 최적, 일반 이진 트리: 삽입 불가","BST: 항상 O(1) 탐색, 힙: 중위순회 정렬됨, 일반 이진 트리: 균형 유지"],"correct_index":0,"explanation":"BST는 중위 순회 시 정렬된 결과를 가집니다. 힙은 최대/최소 힙에서 부모가 항상 자식보다 크거나 작습니다. 일반 이진 트리는 노드 값에 순서 제약이 없습니다."},{"question":"다음 중 그래프에서 최단 경로를 찾는 알고리즘이 아닌 것은?","code":null,"options":["DFS","BFS (가중치 없는 그래프)","다익스트라 (가중치 있는 그래프)","벨만-포드 (음수 가중치 포함)"],"correct_index":0,"explanation":"DFS는 최단 경로를 보장하지 않습니다. 한 방향으로 깊이 탐색하므로 처음 찾은 경로가 최단이 아닐 수 있습니다. BFS는 가중치 없는 그래프에서 최단 경로를 보장합니다."},{"question":"트리에서 두 노드의 최소 공통 조상(LCA: Lowest Common Ancestor)을 찾는 가장 효율적인 접근은?","code":null,"options":["루트에서 각 노드까지의 경로를 구한 뒤 마지막 공통 노드를 찾는다","BFS로 두 노드를 동시에 탐색한다","모든 노드를 방문하여 비교한다","이진 탐색으로 노드를 찾는다"],"correct_index":0,"explanation":"기본적인 LCA 알고리즘은 루트에서 두 노드까지의 경로를 각각 구하고, 두 경로에서 마지막으로 공통되는 노드를 찾습니다. BST의 경우 현재 노드가 두 값 사이에 있으면 LCA임을 O(h)에 판단할 수 있습니다."},{"question":"다음 중 위상 정렬을 실생활에 적용하는 올바른 예시는?","code":null,"options":["대학교 수강 신청 시 선수과목 순서 결정","SNS 친구 추천 알고리즘","내비게이션의 최단 경로 탐색","검색 엔진의 웹 페이지 랭킹"],"correct_index":0,"explanation":"위상 정렬은 의존 관계가 있는 작업의 순서를 결정합니다. 선수과목처럼 A를 먼저 이수해야 B를 수강할 수 있는 경우가 전형적인 예입니다. 친구 추천은 BFS, 최단 경로는 다익스트라, 페이지 랭킹은 PageRank 알고리즘을 사용합니다."}]}', 360);
